from dataclasses import dataclass

from engine.cards import Aspect, CardDefinition, CardType
from engine.state import PlayerState


@dataclass(frozen=True)
class ResourceProduction:
    """Resources generated by a player's vault."""

    blood: int = 0
    malice: int = 0
    cards: int = 0


def calculate_vault_resources(
    player: PlayerState,
    card_definitions: dict[str, CardDefinition],
) -> ResourceProduction:
    """Calculate resource production without modifying game state."""

    total_blood = 0
    total_malice = 0
    total_cards = 0

    vault_cards = list(player.vault)

    # The monster contributes its resource bar to the vault.
    if player.monster is not None:
        vault_cards.append(player.monster)

    for card in vault_cards:
        definition = card_definitions.get(card.card_id)

        if definition is None:
            raise ValueError(
                f"Missing card definition: {card.card_id}"
            )

        total_blood += definition.blood_production
        total_malice += definition.malice_production
        total_cards += definition.draw_production

    return ResourceProduction(
        blood=total_blood,
        malice=total_malice,
        cards=total_cards,
    )


def calculate_vault_loyalty(
    player: PlayerState,
    card_definitions: dict[str, CardDefinition],
) -> dict[Aspect, int]:
    """Calculate the aspect icons available in a player's vault."""

    loyalty = {aspect: 0 for aspect in Aspect}

    vault_cards = list(player.vault)

    if player.monster is not None:
        vault_cards.append(player.monster)

    for card in vault_cards:
        definition = card_definitions.get(card.card_id)

        if definition is None:
            raise ValueError(
                f"Missing card definition: {card.card_id}"
            )

        for aspect, amount in definition.vault_aspects.items():
            loyalty[aspect] += amount

    return loyalty


def meets_loyalty(
    player: PlayerState,
    card: CardDefinition,
    card_definitions: dict[str, CardDefinition],
) -> bool:
    """Check whether a player meets a card's loyalty requirements."""

    available = calculate_vault_loyalty(
        player,
        card_definitions,
    )

    return all(
        available.get(aspect, 0) >= required
        for aspect, required in card.loyalty.items()
    )


def can_play_card(
    player: PlayerState,
    card_instance_id: int,
    card_definitions: dict[str, CardDefinition],
) -> bool:
    """Check whether a card can be played from hand."""

    card = next(
        (c for c in player.hand if c.instance_id == card_instance_id),
        None,
    )

    if card is None:
        return False

    definition = card_definitions.get(card.card_id)

    if definition is None:
        raise ValueError(
            f"Missing card definition: {card.card_id}"
        )

    if definition.card_type not in (
        CardType.ASSET,
        CardType.MINION,
        CardType.EVENT,
    ):
        return False

    # Card effects are not implemented yet.
    # Do not allow events whose effects cannot be resolved.
    if (
        definition.card_type == CardType.EVENT
        and definition.ability_text.strip()
    ):
        return False

    if player.blood < definition.cost:
        return False

    return meets_loyalty(
        player,
        definition,
        card_definitions,
    )